import{_ as s,C as o,o as i,c as n,ag as a,E as r}from"./chunks/framework.CtWPcAmt.js";const m=JSON.parse('{"title":"Draft Products","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/draft-products.md","filePath":"catalog/draft-products.md","lastUpdated":1786111645000}'),d={name:"catalog/draft-products.md"};function l(c,t,p,u,f,h){const e=o("ImagePopup");return i(),n("div",null,[t[0]||(t[0]=a('<h1 id="draft-products" tabindex="-1">Draft Products <a class="header-anchor" href="#draft-products" aria-label="Permalink to &quot;Draft Products&quot;">​</a></h1><p>A seller doesn&#39;t have to finish a product in one sitting. <strong>Save as Draft</strong> keeps a work-in-progress listing private — it isn&#39;t sent to the admin for approval and never appears on the storefront — until the seller is ready to submit it.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How a product becomes (and stays) a draft</li><li>How drafts appear in the products list</li><li>How a draft is submitted for approval</li></ul></div><h2 id="how-drafts-happen" tabindex="-1">How drafts happen <a class="header-anchor" href="#how-drafts-happen" aria-label="Permalink to &quot;How drafts happen&quot;">​</a></h2><p>Every product you create from scratch starts life as a <strong>draft</strong>, so you can build it up safely. While creating or editing a product — or listing one with <a href="/catalog/selling-existing-products">Sell as Yours</a> — the form gives you two choices:</p>',5)),r(e,{src:"/images/draft-products/edit-draft-buttons.png",alt:"Save as Draft and Submit on the product form"}),t[1]||(t[1]=a('<ul><li><strong>Save as Draft</strong> — stores what you&#39;ve entered and keeps the product a draft so you can come back to it. It relaxes the checks a submission enforces: when you&#39;re listing a product with <em>Sell as Yours</em>, details like condition and description can be left blank. A few core essentials (such as SKU and URL key) are still required to save.</li><li><strong>Submit</strong> — validates the listing and sends it into the approval flow.</li></ul><h2 id="finding-your-drafts" tabindex="-1">Finding your drafts <a class="header-anchor" href="#finding-your-drafts" aria-label="Permalink to &quot;Finding your drafts&quot;">​</a></h2><p>In <strong>Catalog → Products</strong>, the <strong>Draft Status</strong> column marks each product as <strong>Draft</strong> or <strong>Submitted</strong>, and you can filter the list by it. A draft&#39;s price, stock, images, and every other detail are all saved and fully editable.</p>',3)),r(e,{src:"/images/draft-products/products-list-draft.png",alt:"Products list showing a draft"}),t[2]||(t[2]=a('<h2 id="publishing-a-draft" tabindex="-1">Publishing a draft <a class="header-anchor" href="#publishing-a-draft" aria-label="Permalink to &quot;Publishing a draft&quot;">​</a></h2><p>Open the draft, complete the remaining details, and <strong>Submit</strong>. It then enters the normal approval flow — the admin reviews it, and once approved it goes live. See <a href="/catalog/product-management#drafts-submission-and-approval">Product Management</a> for the approval side.</p><div class="tip custom-block"><p class="custom-block-title">Rejection reasons</p><p>If the admin rejects a submitted product, they can attach a <strong>reason</strong>, which you&#39;ll see on the listing (its status shows <strong>Rejected</strong>) — so it&#39;s clear what to fix before resubmitting.</p></div>',3))])}const _=s(d,[["render",l]]);export{m as __pageData,_ as default};
